1	//! Feedback command implementation.
2	//!
3	//! Captures and manages friction points during dogfooding, with automatic
4	//! session correlation and optional external delivery via GitHub issues
5	//! or email.
6	
7	use anyhow::Result;
8	use clap::{Args, Subcommand};
9	
10	use crate::feedback::delivery::{
11	    self, build_github_url, build_mailto_url, build_preview, build_title, DeliveryMethod,
12	};
13	use crate::feedback::{default_store_path, FeedbackEntry, FeedbackStatus, FeedbackStore};
14	use crate::session::{default_store_path as session_store_path, Session, SessionId, SessionStore};
15	use crate::ui::{Prompt, PromptOption, PromptResult, PromptType, UserInterface};
16	
17	use super::dispatcher::{Command, CommandResult};
18	
19	/// Known feedback categories that map to delivery routing.
20	const KNOWN_CATEGORIES: &[&str] = &["bug", "feature", "ux", "other"];
21	
22	/// Arguments for the `feedback` command.
23	#[derive(Debug, Clone, Args)]
24	pub struct FeedbackArgs {
25	    #[command(subcommand)]
26	    pub command: Option<FeedbackSubcommand>,
27	
28	    /// Feedback message (when not using a subcommand).
29	    pub message: Vec<String>,
30	
31	    /// Tags for categorization.
32	    #[arg(short, long, value_delimiter = ',')]
33	    pub tag: Vec<String>,
34	
35	    /// Session ID to attach (defaults to most recent).
36	    #[arg(long)]
37	    pub session: Option<String>,
38	
39	    /// Skip the delivery prompt (save locally only).
40	    #[arg(long)]
41	    pub no_deliver: bool,
42	}
43	
44	/// Feedback subcommands.
45	#[derive(Debug, Clone, Subcommand)]
46	pub enum FeedbackSubcommand {
47	    /// List feedback entries.
48	    List {
49	        /// Filter by status (open, resolved, wontfix).
50	        #[arg(long)]
51	        status: Option<String>,
52	        /// Filter by tag.
53	        #[arg(long)]
54	        tag: Option<String>,
55	        /// Show all (including resolved).
56	        #[arg(long)]
57	        all: bool,
58	    },
59	    /// Resolve a feedback entry.
60	    Resolve {
61	        /// Feedback ID.
62	        id: String,
63	        /// Resolution note.
64	        #[arg(short, long)]
65	        note: Option<String>,
66	    },
67	    /// Show feedback for a session.
68	    Session {
69	        /// Session ID (defaults to most recent).
70	        id: Option<String>,
71	    },
72	}
73	
74	/// The feedback command implementation.
75	pub struct FeedbackCommand {
76	    args: FeedbackArgs,
77	}
78	
79	impl FeedbackCommand {
80	    /// Create a new feedback command.
81	    pub fn new(args: FeedbackArgs) -> Self {
82	        Self { args }
83	    }
84	}
85	
86	impl Command for FeedbackCommand {
87	    fn execute(&self, ui: &mut dyn UserInterface) -> crate::error::Result<CommandResult> {
88	        let store = FeedbackStore::new(default_store_path());
89	
90	        let exit_code = match &self.args.command {
91	            Some(FeedbackSubcommand::List { status, tag, all }) => {
92	                list_feedback(&store, status.clone(), tag.clone(), *all, ui)?
93	            }
94	            Some(FeedbackSubcommand::Resolve { id, note }) => {
95	                resolve_feedback(&store, id, note.clone(), ui)?
96	            }
97	            Some(FeedbackSubcommand::Session { id }) => {
98	                show_session_feedback(&store, id.clone(), ui)?
99	            }
100	            None => {
101	                if self.args.message.is_empty() {
102	                    capture_interactive(&store, self.args.tag.clone(), self.args.no_deliver, ui)?
103	                } else {
104	                    let message = self.args.message.join(" ");
105	                    let category = category_from_tags(&self.args.tag);
106	                    capture_feedback(
107	                        &store,
108	                        &message,
109	                        &category,
110	                        self.args.tag.clone(),
111	                        self.args.session.clone(),
112	                        self.args.no_deliver,
113	                        ui,
114	                    )?
115	                }
116	            }
117	        };
118	
119	        Ok(if exit_code == 0 {
120	            CommandResult::success()
121	        } else {
122	            CommandResult::failure(exit_code)
123	        })
124	    }
125	}
126	
127	/// Extract a delivery category from the tag list.
128	///
129	/// Uses the first tag that matches a known category. Falls back to "other".
130	fn category_from_tags(tags: &[String]) -> String {
131	    tags.iter()
132	        .find(|t| KNOWN_CATEGORIES.contains(&t.as_str()))
133	        .cloned()
134	        .unwrap_or_else(|| "other".to_string())
135	}
136	
137	fn capture_feedback(
138	    store: &FeedbackStore,
139	    message: &str,
140	    category: &str,
141	    tags: Vec<String>,
142	    session_id: Option<String>,
143	    no_deliver: bool,
144	    ui: &mut dyn UserInterface,
145	) -> Result<i32> {
146	    let session_store = SessionStore::new(session_store_path());
147	
148	    // Get session ID (provided, or most recent)
149	    let session = if let Some(id_str) = session_id {
150	        SessionId::parse(&id_str)
151	    } else {
152	        session_store.get_latest()?.map(|s| s.id)
153	    };
154	
155	    let mut entry = FeedbackEntry::new(message);
156	    if !tags.is_empty() {
157	        entry = entry.with_tags(tags);
158	    }
159	    if let Some(sid) = session.clone() {
160	        entry = entry.with_session(sid.clone());
161	    }
162	
163	    store.append(&entry)?;
164	
165	    let session_note = session
166	        .as_ref()
167	        .map(|s| format!(" (session {})", s))
168	        .unwrap_or_default();
169	
170	    ui.success(&format!("Feedback captured{}", session_note));
171	
172	    // Offer external delivery if interactive and not suppressed
173	    if !no_deliver && ui.is_interactive() {
174	        let full_session = session.and_then(|sid| session_store.load(&sid).ok());
175	        offer_delivery(store, &entry, category, full_session.as_ref(), ui)?;
176	    }
177	
178	    Ok(0)
179	}
