62	impl ConfigPaths {
63	    /// Discover config files for the given project root.
64	    pub fn discover(project_root: &Path) -> Self {
65	        Self {
66	            extends: Vec::new(), // Populated later after parsing project config
67	            user_global: Self::find_user_global(),
68	            project: Self::find_project_config(project_root),
69	            split_steps: Self::find_split_files(project_root, "steps"),
70	            split_workflows: Self::find_split_files(project_root, "workflows"),
71	            project_local: Self::find_project_local(project_root),
72	        }
73	    }
74	
75	    /// Find user's global config at ~/.bivvy/config.yml
76	    fn find_user_global() -> Option<PathBuf> {
77	        let path = crate::sys::home_dir()?.join(".bivvy").join("config.yml");
78	        if path.exists() {
79	            Some(path)
80	        } else {
81	            None
82	        }
83	    }
84	
85	    /// Find project config at .bivvy/config.yml
86	    fn find_project_config(project_root: &Path) -> Option<PathBuf> {
87	        let path = project_root.join(".bivvy").join("config.yml");
88	        if path.exists() {
89	            Some(path)
90	        } else {
91	            None
92	        }
93	    }
94	
95	    /// Find local overrides at .bivvy/config.local.yml
96	    fn find_project_local(project_root: &Path) -> Option<PathBuf> {
97	        let path = project_root.join(".bivvy").join("config.local.yml");
98	        if path.exists() {
99	            Some(path)
100	        } else {
101	            None
102	        }
103	    }
104	
105	    /// Find YAML files in `.bivvy/<subdir>/`.
106	    ///
107	    /// Returns sorted paths for deterministic merge order.
108	    fn find_split_files(project_root: &Path, subdir: &str) -> Vec<PathBuf> {
109	        let dir = project_root.join(".bivvy").join(subdir);
110	        if !dir.is_dir() {
111	            return Vec::new();
112	        }
113	
114	        let mut files: Vec<PathBuf> = fs::read_dir(&dir)
115	            .into_iter()
116	            .flatten()
117	            .filter_map(|entry| entry.ok())
118	            .map(|entry| entry.path())
119	            .filter(|path| {
120	                path.extension()
121	                    .is_some_and(|ext| ext == "yml" || ext == "yaml")
122	            })
123	            .collect();
124	
125	        files.sort();
126	        files
127	    }
128	
129	    /// Returns all existing config paths in merge order (excludes split files).
130	    pub fn all_existing(&self) -> Vec<&PathBuf> {
131	        let mut paths = Vec::new();
132	
133	        for p in &self.extends {
134	            paths.push(p);
135	        }
136	
137	        if let Some(p) = &self.user_global {
138	            paths.push(p);
139	        }
140	
141	        if let Some(p) = &self.project {
142	            paths.push(p);
143	        }
144	
145	        if let Some(p) = &self.project_local {
146	            paths.push(p);
147	        }
148	
149	        paths
150	    }
