166	/// Ensure the global config directory, config file, and schema exist.
167	///
168	/// Creates `~/.bivvy/config.yml` (with commented-out examples) and
169	/// `~/.bivvy/schema.json` if they don't already exist. Called on every
170	/// invocation so every install path (Homebrew, `cargo install`,
171	/// `install.sh`) gets the global config without relying on the installer.
172	///
173	/// The schema file is always rewritten so it stays current after upgrades.
174	///
175	/// Failures are silently ignored — a missing global config is not fatal.
176	pub fn ensure_global_config() {
177	    let Some(home) = crate::sys::home_dir() else {
178	        return;
179	    };
180	    ensure_global_config_in(home);
181	}
182	
183	/// Inner implementation that accepts an explicit home directory.
184	///
185	/// Separated from [`ensure_global_config`] so tests can point at a temp dir.
186	fn ensure_global_config_in(home: PathBuf) {
187	    let bivvy_dir = home.join(".bivvy");
188	
189	    if fs::create_dir_all(&bivvy_dir).is_err() {
190	        return;
191	    }
192	
193	    // Write schema.json on every run so it stays current after upgrades.
194	    let schema_path = bivvy_dir.join("schema.json");
195	    let _ = fs::write(&schema_path, crate::lint::schema_json());
196	
197	    // Only create config.yml if it doesn't exist yet.
198	    let config_path = bivvy_dir.join("config.yml");
199	    if !config_path.exists() {
200	        let schema_display = schema_path.display();
201	        let content = format!(
202	            "\
203	# yaml-language-server: $schema={schema_display}
204	#
205	# Bivvy global configuration
206	# Docs: https://bivvy.dev/configuration
207	#
208	# Settings here apply to ALL projects on this machine.
209	# Project-level .bivvy/config.yml overrides these defaults.
210	
211	# settings:
212	#   defaults:
213	#     output: verbose        # verbose | quiet | silent
214	#     auto_run: true         # auto-run steps or prompt first
215	#     prompt_on_rerun: false # prompt before re-running completed steps
216	#   parallel: false          # enable parallel step execution
217	#   max_parallel: 4          # max concurrent steps (when parallel: true)
218	#   auto_update: true        # check for bivvy updates in the background
219	#   logging: false           # enable JSONL event logging
220	"
221	        );
222	
223	        let _ = fs::write(&config_path, content);
224	    }
225	}
