1	//! Session wrapper for CLI commands.
2	//!
3	//! This module provides session tracking integration for CLI command execution.
4	
5	use anyhow::Result;
6	
7	use crate::session::{default_store_path, Session, SessionId, SessionMetadata, SessionStore};
8	
9	/// Wraps command execution with session tracking.
10	pub struct SessionWrapper {
11	    store: SessionStore,
12	    current_id: SessionId,
13	    metadata: SessionMetadata,
14	    stdout_buffer: Vec<u8>,
15	    stderr_buffer: Vec<u8>,
16	}
17	
18	impl SessionWrapper {
19	    /// Create a new session wrapper.
20	    pub fn new(command: &str, args: Vec<String>) -> Self {
21	        Self {
22	            store: SessionStore::new(default_store_path()),
23	            current_id: SessionId::new(),
24	            metadata: SessionMetadata::new(command, args),
25	            stdout_buffer: Vec::new(),
26	            stderr_buffer: Vec::new(),
27	        }
28	    }
29	
30	    /// Get the current session ID.
31	    pub fn session_id(&self) -> &SessionId {
32	        &self.current_id
33	    }
34	
35	    /// Get mutable access to metadata for adding context.
36	    pub fn metadata_mut(&mut self) -> &mut SessionMetadata {
37	        &mut self.metadata
38	    }
39	
40	    /// Capture stdout.
41	    pub fn capture_stdout(&mut self, s: &str) {
42	        self.stdout_buffer.extend_from_slice(s.as_bytes());
43	    }
44	
45	    /// Capture stderr.
46	    pub fn capture_stderr(&mut self, s: &str) {
47	        self.stderr_buffer.extend_from_slice(s.as_bytes());
48	    }
49	
50	    /// Finalize and save the session.
51	    pub fn finalize(mut self, exit_code: i32) -> Result<SessionId> {
52	        let stdout = String::from_utf8_lossy(&self.stdout_buffer).to_string();
53	        let stderr = String::from_utf8_lossy(&self.stderr_buffer).to_string();
54	
55	        self.metadata.finalize(exit_code, stdout, stderr);
56	
57	        let session = Session {
58	            id: self.current_id.clone(),
59	            metadata: self.metadata,
60	        };
61	
62	        self.store.save(&session)?;
63	
64	        // Cleanup old sessions (keep last 100)
65	        let _ = self.store.cleanup(100);
66	
67	        Ok(self.current_id)
68	    }
69	
70	    /// Get the latest session ID (for feedback command).
71	    pub fn get_latest_session_id() -> Result<Option<SessionId>> {
72	        let store = Self::get_store();
73	        Ok(store.get_latest()?.map(|s| s.id))
74	    }
75	
76	    /// Get the session store for reading sessions.
77	    pub fn get_store() -> SessionStore {
78	        SessionStore::new(default_store_path())
79	    }
80	}
81	
82	#[cfg(test)]
83	mod tests {
84	    use super::*;
85	    use tempfile::TempDir;
86	
87	    // Use a custom store for testing to avoid polluting the real store
88	    fn create_test_wrapper(
89	        command: &str,
90	        args: Vec<String>,
91	        store_path: std::path::PathBuf,
92	    ) -> SessionWrapper {
93	        SessionWrapper {
94	            store: SessionStore::new(store_path),
95	            current_id: SessionId::new(),
96	            metadata: SessionMetadata::new(command, args),
97	            stdout_buffer: Vec::new(),
98	            stderr_buffer: Vec::new(),
99	        }
100	    }
101	
102	    #[test]
103	    fn session_wrapper_creation() {
104	        let wrapper = SessionWrapper::new("run", vec!["--verbose".to_string()]);
105	        assert!(wrapper.session_id().as_str().starts_with("sess_"));
106	    }
107	
108	    #[test]
109	    fn session_wrapper_capture_output() {
110	        let temp = TempDir::new().unwrap();
111	        let mut wrapper = create_test_wrapper("list", vec![], temp.path().join("sessions"));
112	
113	        wrapper.capture_stdout("Hello\n");
114	        wrapper.capture_stdout("World\n");
115	        wrapper.capture_stderr("Warning: something\n");
116	
117	        let id = wrapper.finalize(0).unwrap();
118	
119	        // Verify the session was saved
120	        let store = SessionStore::new(temp.path().join("sessions"));
121	        let session = store.load(&id).unwrap();
122	
123	        assert!(session.metadata.stdout.contains("Hello"));
124	        assert!(session.metadata.stdout.contains("World"));
125	        assert!(session.metadata.stderr.contains("Warning"));
126	    }
127	
128	    #[test]
129	    fn session_wrapper_metadata_modification() {
130	        let temp = TempDir::new().unwrap();
131	        let mut wrapper = create_test_wrapper("run", vec![], temp.path().join("sessions"));
132	
133	        wrapper.metadata_mut().set_flag("verbose", true);
134	        wrapper.metadata_mut().context.workflow = Some("default".to_string());
135	
136	        let id = wrapper.finalize(0).unwrap();
137	
138	        let store = SessionStore::new(temp.path().join("sessions"));
139	        let session = store.load(&id).unwrap();
140	
141	        assert_eq!(
142	            session.metadata.flags.get("verbose"),
143	            Some(&serde_json::json!(true))
144	        );
145	        assert_eq!(
146	            session.metadata.context.workflow,
147	            Some("default".to_string())
148	        );
149	    }
150	
151	    #[test]
152	    fn session_wrapper_finalize_exit_code() {
153	        let temp = TempDir::new().unwrap();
154	        let wrapper = create_test_wrapper("run", vec![], temp.path().join("sessions"));
155	
156	        let id = wrapper.finalize(1).unwrap();
157	
158	        let store = SessionStore::new(temp.path().join("sessions"));
159	        let session = store.load(&id).unwrap();
160	
161	        assert_eq!(session.metadata.exit_code, Some(1));
162	    }
163	
164	    #[test]
165	    fn session_wrapper_cleanup_old_sessions() {
166	        let temp = TempDir::new().unwrap();
167	        let store_path = temp.path().join("sessions");
168	
169	        // Create 105 sessions
170	        for i in 0..105 {
171	            let wrapper = create_test_wrapper(&format!("cmd{}", i), vec![], store_path.clone());
172	            wrapper.finalize(0).unwrap();
173	            std::thread::sleep(std::time::Duration::from_millis(2));
174	        }
175	
176	        let store = SessionStore::new(&store_path);
177	        let sessions = store.list_recent(usize::MAX).unwrap();
178	
179	        // Should have at most 100 sessions due to cleanup
180	        assert!(sessions.len() <= 100);
181	    }
182	
183	    #[test]
184	    fn session_wrapper_get_store() {
185	        // Test that get_store returns a valid store
186	        let store = SessionWrapper::get_store();
187	        // Just check the path is set correctly
188	        assert!(store.path().ends_with("sessions"));
189	    }
