191	    #[test]
192	    fn session_wrapper_get_latest_session_id_empty_store() {
193	        let temp = TempDir::new().unwrap();
194	        let store = SessionStore::new(temp.path().join("sessions"));
195	
196	        let latest = store.get_latest().unwrap();
197	        assert!(latest.is_none());
