200	    #[test]
201	    fn session_wrapper_get_latest_session_id_returns_most_recent() {
202	        let temp = TempDir::new().unwrap();
203	        let store_path = temp.path().join("sessions");
204	
205	        // Create two sessions with a small delay so timestamps differ
206	        let first = create_test_wrapper("first", vec![], store_path.clone());
207	        let _first_id = first.finalize(0).unwrap();
208	        std::thread::sleep(std::time::Duration::from_millis(2));
209	
210	        let second = create_test_wrapper("second", vec![], store_path.clone());
211	        let second_id = second.finalize(0).unwrap();
212	
213	        let store = SessionStore::new(&store_path);
214	        let latest = store.get_latest().unwrap().expect("should have a session");
215	        assert_eq!(latest.id, second_id);
216	        assert_eq!(latest.metadata.command, "second");
217	    }
218	
219	    #[test]
220	    fn session_wrapper_capture_multiple_calls() {
221	        let temp = TempDir::new().unwrap();
222	        let mut wrapper = create_test_wrapper("test", vec![], temp.path().join("sessions"));
223	
224	        // Multiple capture calls
225	        wrapper.capture_stdout("line1\n");
226	        wrapper.capture_stdout("line2\n");
227	        wrapper.capture_stdout("line3\n");
