451	        );
452	
453	        let cache = CacheStore::new(temp.path().join("cache"));
454	        let http = HttpFetcher::new();
455	        let git = GitFetcher::new(temp.path().join("clones"));
456	
457	        let sources = vec![make_source(
458	            bare.to_string_lossy().to_string(),
459	            TemplateSourceKind::Git,
460	        )];
461	
462	        let loader = RemoteLoader::new(&sources, &http, &git, &cache).unwrap();
463	        assert!(
464	            loader.has("ok-tool"),
465	            "valid template should still be loaded even if a sibling fails to parse"
466	        );
467	    }
