    #[test]
    fn fetch_if_changed_without_etag_does_normal_fetch() {
        let server = MockServer::start();

        server.mock(|when, then| {
            when.method(GET).path("/no-etag-check.yml");
            then.status(200)
                .header("ETag", "\"new-etag\"")
