1	//! Background auto-update functionality.
2	//!
3	//! Provides automatic, zero-interaction updates for bivvy. On each run,
4	//! a background process checks for new versions and either:
5	//! - Runs the package manager update command (cargo/homebrew installs)
6	//! - Downloads and stages a new binary (manual installs)
7	//!
8	//! For manual installs, the staged binary is swapped in on the next startup.
9	//! For package-manager installs, the update is applied immediately by the
10	//! package manager and takes effect on the next invocation.
11	
12	use anyhow::{Context, Result};
13	use chrono::{DateTime, Utc};
14	use serde::{Deserialize, Serialize};
15	use std::fs;
16	use std::path::PathBuf;
17	use std::process::{Command, Stdio};
18	
19	use super::version::{check_for_updates, UpdateInfo};
20	use super::{detect_install_method, InstallMethod};
21	
22	/// Metadata for a staged binary update (manual installs only).
23	#[derive(Debug, Clone, Serialize, Deserialize)]
24	pub struct StagedUpdate {
25	    /// The version that was downloaded.
26	    pub version: String,
27	    /// When the binary was staged.
28	    pub staged_at: DateTime<Utc>,
29	}
30	
31	/// Get the staging directory for downloaded binaries.
32	fn staging_dir() -> Option<PathBuf> {
33	    crate::sys::data_dir().map(|d| d.join("bivvy").join("staged-update"))
34	}
35	
36	/// Get the path to the staged binary.
37	fn staged_binary_path() -> Option<PathBuf> {
38	    staging_dir().map(|d| {
39	        if cfg!(windows) {
40	            d.join("bivvy.exe")
41	        } else {
42	            d.join("bivvy")
43	        }
44	    })
45	}
46	
47	/// Get the path to the staging metadata file.
48	fn staged_metadata_path() -> Option<PathBuf> {
49	    staging_dir().map(|d| d.join("metadata.json"))
50	}
51	
52	/// Get the path to the background update lock file.
53	fn lock_path() -> Option<PathBuf> {
54	    crate::sys::cache_dir().map(|d| d.join("bivvy").join("update.lock"))
55	}
56	
57	/// Check if a staged update is ready to apply.
58	pub fn check_staged_update() -> Option<StagedUpdate> {
59	    let meta_path = staged_metadata_path()?;
60	    let content = fs::read_to_string(meta_path).ok()?;
61	    serde_json::from_str(&content).ok()
62	}
63	
64	/// Apply a staged update by replacing the current binary.
65	///
66	/// Only applies to manual installs — for cargo/homebrew, the package manager
67	/// already placed the new binary. Returns the new version string if applied.
68	pub fn apply_staged_update() -> Result<Option<String>> {
69	    let staged = match check_staged_update() {
70	        Some(s) => s,
71	        None => return Ok(None),
72	    };
73	
74	    let method = detect_install_method();
75	
76	    // Staged binary replacement only applies to manual installs.
77	    // For package-manager installs, the manager already updated the binary.
78	    if !matches!(method, InstallMethod::Manual { .. }) {
79	        let _ = clear_staged_update();
80	        return Ok(None);
81	    }
82	
83	    let staged_binary = match staged_binary_path() {
84	        Some(p) if p.exists() => p,
85	        _ => return Ok(None),
86	    };
87	
88	    let current_exe = std::env::current_exe().context("Failed to locate current executable")?;
89	
90	    replace_binary(&staged_binary, &current_exe)?;
91	
92	    let _ = clear_staged_update();
93	
94	    Ok(Some(staged.version))
95	}
96	
97	/// Replace the current binary with the staged one (Unix).
98	#[cfg(unix)]
99	fn replace_binary(staged: &PathBuf, current: &PathBuf) -> Result<()> {
100	    use std::os::unix::fs::PermissionsExt;
101	
102	    // Copy to a temp file in the same directory (ensures same-filesystem rename)
103	    let temp = current.with_extension("new");
104	    fs::copy(staged, &temp).context("Failed to copy staged binary")?;
105	
106	    // Preserve original permissions and ensure executable
107	    let perms = fs::metadata(current)
108	        .map(|m| m.permissions())
109	        .unwrap_or_else(|_| {
110	            let mut p = fs::metadata(&temp).unwrap().permissions();
111	            p.set_mode(0o755);
112	            p
113	        });
114	    fs::set_permissions(&temp, perms)?;
115	
116	    // Atomic rename
117	    fs::rename(&temp, current).context("Failed to replace binary")?;
118	
119	    Ok(())
120	}
121	
122	/// Replace the current binary with the staged one (Windows).
123	#[cfg(windows)]
124	fn replace_binary(staged: &PathBuf, current: &PathBuf) -> Result<()> {
125	    let old = current.with_extension("old.exe");
126	
127	    // Clean up any leftover from a previous update
128	    let _ = fs::remove_file(&old);
129	
130	    // Windows allows renaming a running executable
131	    fs::rename(current, &old).context("Failed to rename current binary")?;
132	    fs::copy(staged, current).context("Failed to copy new binary into place")?;
133	
134	    // Best-effort cleanup (may fail if old binary is still running)
135	    let _ = fs::remove_file(&old);
136	
137	    Ok(())
138	}
139	
140	/// Remove all staged update files.
141	fn clear_staged_update() -> Result<()> {
142	    if let Some(dir) = staging_dir() {
143	        if dir.exists() {
144	            fs::remove_dir_all(&dir)?;
145	        }
146	    }
147	    Ok(())
148	}
149	
150	/// Check whether a background update process is already running (or ran recently).
151	///
152	/// Uses a lock file with a timestamp. If the lock is less than 5 minutes old,
153	/// we assume the process is still active or just finished.
154	fn is_update_process_running() -> bool {
155	    let path = match lock_path() {
156	        Some(p) => p,
157	        None => return false,
158	    };
159	
160	    if let Ok(meta) = fs::metadata(&path) {
161	        if let Ok(modified) = meta.modified() {
162	            if let Ok(age) = modified.elapsed() {
163	                return age.as_secs() < 300;
164	            }
165	        }
166	    }
167	
168	    false
169	}
170	
171	/// Write a lock file to prevent concurrent background update processes.
172	fn write_lock_file() -> Result<()> {
173	    let path = lock_path().context("No cache directory for lock file")?;
174	    if let Some(parent) = path.parent() {
175	        fs::create_dir_all(parent)?;
176	    }
177	    fs::write(&path, Utc::now().to_rfc3339())?;
178	    Ok(())
179	}
180	
181	/// Remove the lock file after the background process completes.
182	fn remove_lock_file() {
183	    if let Some(path) = lock_path() {
184	        let _ = fs::remove_file(path);
185	    }
186	}
187	
188	/// Read the `auto_update` setting from the system config (`~/.bivvy/config.yml`).
189	///
190	/// Returns the configured value, or `true` (the default) if the system
191	/// config doesn't exist or doesn't contain the setting.
192	pub fn is_auto_update_enabled() -> bool {
193	    let path = match crate::sys::home_dir() {
194	        Some(h) => h.join(".bivvy").join("config.yml"),
195	        None => return true,
196	    };
197	
198	    let content = match fs::read_to_string(&path) {
199	        Ok(c) => c,
200	        Err(_) => return true, // No system config → default on
201	    };
202	
203	    // Parse just enough to read settings.auto_update
204	    let value: serde_yaml::Value = match serde_yaml::from_str(&content) {
205	        Ok(v) => v,
206	        Err(_) => return true,
207	    };
208	
209	    value
210	        .get("settings")
211	        .and_then(|s| s.get("auto_update"))
212	        .and_then(|v| v.as_bool())
213	        .unwrap_or(true)
214	}
215	
216	/// Decide whether to spawn a background update process.
217	pub fn should_spawn_background_update(is_interactive: bool, is_ci: bool) -> bool {
218	    // Never auto-update in CI
219	    if is_ci {
220	        return false;
221	    }
222	
223	    // Only auto-update in interactive sessions
224	    if !is_interactive {
225	        return false;
226	    }
227	
228	    // Respect the user's config setting
229	    if !is_auto_update_enabled() {
230	        return false;
231	    }
232	
233	    // Don't spawn if another process is already running
234	    if is_update_process_running() {
235	        return false;
236	    }
237	
238	    // Don't spawn if there's already a staged update waiting
239	    if check_staged_update().is_some() {
240	        return false;
241	    }
242	
243	    true
244	}
245	
246	/// Spawn a detached background process to check for and apply updates.
247	///
248	/// The background process is the same bivvy binary, invoked with the
249	/// `BIVVY_SELF_UPDATE_BG=1` environment variable. It runs silently
250	/// with no stdin/stdout/stderr.
251	pub fn spawn_background_update() -> Result<()> {
252	    let exe = std::env::current_exe().context("Failed to locate current executable")?;
253	
254	    let mut cmd = Command::new(exe);
255	    cmd.env("BIVVY_SELF_UPDATE_BG", "1")
256	        .stdin(Stdio::null())
257	        .stdout(Stdio::null())
258	        .stderr(Stdio::null());
259	
260	    // On Unix, create a new session so the child survives if the parent's
261	    // terminal closes.
262	    #[cfg(unix)]
263	    {
264	        use std::os::unix::process::CommandExt;
265	        unsafe {
266	            cmd.pre_exec(|| {
267	                libc::setsid();
268	                Ok(())
269	            });
270	        }
271	    }
272	
273	    // On Windows, use DETACHED_PROCESS so the child has no console window.
274	    #[cfg(windows)]
275	    {
276	        use std::os::windows::process::CommandExt;
277	        cmd.creation_flags(0x00000008); // DETACHED_PROCESS
278	    }
279	
280	    cmd.spawn()
281	        .context("Failed to spawn background update process")?;
282	
283	    Ok(())
284	}
285	
286	/// Entry point for the background update process.
287	///
288	/// Called when bivvy is invoked with `BIVVY_SELF_UPDATE_BG=1`.
289	/// Checks for updates and either runs the package manager command
290	/// or downloads and stages the new binary.
291	pub fn perform_background_update() -> Result<()> {
292	    write_lock_file()?;
293	
294	    let result = do_background_update();
295	
296	    remove_lock_file();
297	
298	    result
299	}
300	
301	/// Inner logic for background updates, separated so the lock file
302	/// is always cleaned up regardless of success/failure.
303	fn do_background_update() -> Result<()> {
304	    let info = match check_for_updates() {
305	        Some(info) if info.update_available => info,
306	        _ => return Ok(()),
307	    };
308	
309	    let method = detect_install_method();
310	
311	    match method {
312	        InstallMethod::Cargo => {
313	            run_package_manager_update("cargo", &["install", "bivvy", "--force"])?;
314	        }
315	        InstallMethod::Homebrew => {
316	            run_package_manager_update("brew", &["upgrade", "bivvy"])?;
317	        }
318	        InstallMethod::Manual { .. } => {
319	            stage_binary_update(&info)?;
320	        }
321	        InstallMethod::Unknown => {
322	            // Can't auto-update — silently skip
323	        }
324	    }
325	
326	    Ok(())
327	}
328	
329	/// Run a package manager's update command silently.
330	fn run_package_manager_update(program: &str, args: &[&str]) -> Result<()> {
331	    let status = Command::new(program)
332	        .args(args)
333	        .stdin(Stdio::null())
334	        .stdout(Stdio::null())
335	        .stderr(Stdio::null())
336	        .status()
337	        .with_context(|| format!("Failed to run {} {}", program, args.join(" ")))?;
338	
339	    if !status.success() {
340	        anyhow::bail!(
341	            "{} {} exited with code {:?}",
342	            program,
343	            args.join(" "),
344	            status.code()
345	        );
346	    }
347	
348	    Ok(())
349	}
350	
351	/// Download the appropriate binary from GitHub releases and stage it.
352	fn stage_binary_update(info: &UpdateInfo) -> Result<()> {
353	    let asset_url = find_platform_asset_url(info)?;
354	
355	    let dir = staging_dir().context("No data directory for staging")?;
356	    fs::create_dir_all(&dir)?;
357	
358	    let binary_path = if cfg!(windows) {
359	        dir.join("bivvy.exe")
360	    } else {
361	        dir.join("bivvy")
362	    };
363	
364	    download_asset(&asset_url, &binary_path)?;
365	
366	    // Write metadata so apply_staged_update knows the version
367	    let metadata = StagedUpdate {
368	        version: info.latest.clone(),
369	        staged_at: Utc::now(),
370	    };
371	    let meta_path = dir.join("metadata.json");
372	    fs::write(meta_path, serde_json::to_string_pretty(&metadata)?)?;
373	
374	    Ok(())
375	}
376	
377	/// Query the GitHub releases API to find the download URL for this platform.
378	fn find_platform_asset_url(info: &UpdateInfo) -> Result<String> {
379	    let target = platform_target();
380	
381	    let client = reqwest::blocking::Client::builder()
382	        .user_agent("bivvy")
383	        .timeout(std::time::Duration::from_secs(30))
384	        .build()?;
385	
386	    let api_url = format!(
387	        "https://api.github.com/repos/bivvy-dev/bivvy/releases/tags/v{}",
388	        info.latest
389	    );
390	
391	    let response: serde_json::Value = client
392	        .get(&api_url)
393	        .send()?
394	        .json()
395	        .context("Failed to parse GitHub releases API response")?;
396	
397	    let assets = response["assets"]
398	        .as_array()
399	        .context("No assets array in release")?;
400	
401	    for asset in assets {
402	        let name = asset["name"].as_str().unwrap_or("");
403	        if name.contains(&target) {
404	            if let Some(url) = asset["browser_download_url"].as_str() {
405	                return Ok(url.to_string());
406	            }
407	        }
408	    }
409	
410	    anyhow::bail!(
411	        "No release asset found for platform '{}' in v{}",
412	        target,
413	        info.latest
414	    )
415	}
416	
417	/// Return the Rust target triple fragment for this platform.
418	///
419	/// Used to match against GitHub release asset filenames (e.g.
420	/// `bivvy-x86_64-apple-darwin`, `bivvy-aarch64-unknown-linux-gnu`).
421	pub fn platform_target() -> String {
422	    let os = match std::env::consts::OS {
423	        "macos" => "apple-darwin",
424	        "linux" => "unknown-linux-gnu",
425	        "windows" => "pc-windows-msvc",
426	        other => other,
427	    };
428	
429	    let arch = std::env::consts::ARCH;
430	
431	    format!("{}-{}", arch, os)
432	}
433	
434	/// Download a file from a URL to a local path.
435	fn download_asset(url: &str, dest: &PathBuf) -> Result<()> {
436	    let client = reqwest::blocking::Client::builder()
437	        .user_agent("bivvy")
438	        .timeout(std::time::Duration::from_secs(120))
439	        .build()?;
440	
441	    let bytes = client
442	        .get(url)
443	        .send()
444	        .context("Failed to download update")?
445	        .bytes()
446	        .context("Failed to read download body")?;
447	
448	    fs::write(dest, &bytes)?;
449	
450	    // Make executable on Unix
451	    #[cfg(unix)]
452	    {
453	        use std::os::unix::fs::PermissionsExt;
454	        let mut perms = fs::metadata(dest)?.permissions();
455	        perms.set_mode(0o755);
456	        fs::set_permissions(dest, perms)?;
457	    }
458	
459	    Ok(())
460	}
461	
462	#[cfg(test)]
463	mod tests {
464	    use super::*;
465	    use tempfile::TempDir;
466	
467	    #[test]
468	    fn platform_target_contains_arch_and_os() {
469	        let target = platform_target();
470	        // Should contain architecture
471	        assert!(
472	            target.contains("x86_64")
473	                || target.contains("aarch64")
474	                || target.contains(std::env::consts::ARCH),
475	            "Target '{}' should contain architecture",
476	            target
477	        );
478	        // Should contain OS identifier
479	        assert!(
480	            target.contains("darwin")
481	                || target.contains("linux")
482	                || target.contains("windows")
483	                || target.contains(std::env::consts::OS),
484	            "Target '{}' should contain OS identifier",
485	            target
486	        );
487	    }
488	
489	    #[test]
490	    fn staged_update_serialization_roundtrip() {
491	        let staged = StagedUpdate {
492	            version: "2.0.0".to_string(),
493	            staged_at: Utc::now(),
494	        };
495	
496	        let json = serde_json::to_string(&staged).unwrap();
497	        let parsed: StagedUpdate = serde_json::from_str(&json).unwrap();
498	
499	        assert_eq!(parsed.version, "2.0.0");
500	    }
501	
502	    #[test]
503	    fn staging_dir_returns_path() {
504	        // On most systems crate::sys::data_dir() is Some
505	        if let Some(dir) = staging_dir() {
506	            assert!(dir.ends_with("staged-update"));
507	        }
508	    }
509	
510	    #[test]
511	    fn staged_binary_path_has_correct_name() {
512	        if let Some(path) = staged_binary_path() {
513	            let name = path.file_name().unwrap().to_string_lossy();
514	            if cfg!(windows) {
515	                assert_eq!(name, "bivvy.exe");
516	            } else {
517	                assert_eq!(name, "bivvy");
518	            }
519	        }
520	    }
521	
522	    #[test]
523	    fn check_staged_update_returns_none_when_no_staging() {
524	        // No staged update should exist in test environment
525	        // (unless a real update was staged, which is unlikely)
526	        // This primarily tests that the function doesn't panic
527	        let _ = check_staged_update();
528	    }
529	
530	    #[test]
531	    fn clear_staged_update_is_idempotent() {
532	        // Should not error even when there's nothing to clear
533	        let result = clear_staged_update();
534	        assert!(result.is_ok());
535	    }
536	
537	    #[test]
538	    fn should_spawn_returns_false_in_ci() {
539	        assert!(!should_spawn_background_update(true, true));
540	    }
541	
542	    #[test]
543	    fn should_spawn_returns_false_when_non_interactive() {
544	        assert!(!should_spawn_background_update(false, false));
545	    }
546	
547	    #[test]
548	    fn should_spawn_returns_true_in_interactive_non_ci() {
549	        // This may still return false if a lock file or staged update exists,
550	        // but the CI and interactive checks should pass
551	        let result = should_spawn_background_update(true, false);
552	        // Can't assert true because lock file state is unpredictable,
553	        // but we at least verify it doesn't panic
554	        let _ = result;
555	    }
556	
557	    #[test]
558	    fn is_update_process_running_returns_false_without_lock() {
559	        // Without a lock file, should be false
560	        // (unless one exists from a real update, but unlikely in test)
561	        let _ = is_update_process_running();
562	    }
563	
564	    #[test]
565	    fn write_and_check_lock_file() {
566	        // Write a lock file and verify it's detected
567	        if write_lock_file().is_ok() {
568	            assert!(is_update_process_running());
569	            remove_lock_file();
570	            // After removal, should no longer be running
571	            // (give a tiny margin for filesystem lag)
572	            assert!(!is_update_process_running());
573	        }
574	    }
575	
576	    #[test]
577	    fn replace_binary_with_temp_files() {
578	        let temp = TempDir::new().unwrap();
579	
580	        // Create a fake "current" binary
581	        let current = temp.path().join("bivvy");
582	        fs::write(&current, b"old version").unwrap();
583	        #[cfg(unix)]
584	        {
585	            use std::os::unix::fs::PermissionsExt;
586	            let mut perms = fs::metadata(&current).unwrap().permissions();
587	            perms.set_mode(0o755);
588	            fs::set_permissions(&current, perms).unwrap();
589	        }
590	
591	        // Create a fake "staged" binary
592	        let staged = temp.path().join("bivvy-staged");
593	        fs::write(&staged, b"new version").unwrap();
594	
595	        // Replace
596	        let result = replace_binary(&staged, &current);
597	        assert!(result.is_ok(), "replace_binary failed: {:?}", result.err());
598	
599	        // Verify content changed
600	        let content = fs::read_to_string(&current).unwrap();
601	        assert_eq!(content, "new version");
602	
603	        // Verify temp file was cleaned up
604	        assert!(!temp.path().join("bivvy.new").exists());
605	    }
606	
607	    #[test]
608	    fn apply_staged_update_returns_none_when_nothing_staged() {
609	        // In test environment, there should be no staged update
610	        let result = apply_staged_update().unwrap();
611	        assert!(result.is_none());
612	    }
613	
614	    #[test]
615	    fn staged_metadata_path_returns_json_file() {
616	        if let Some(path) = staged_metadata_path() {
617	            assert_eq!(path.file_name().unwrap().to_string_lossy(), "metadata.json");
618	        }
619	    }
620	
621	    #[test]
622	    fn lock_path_returns_lock_file() {
623	        if let Some(path) = lock_path() {
624	            assert_eq!(path.file_name().unwrap().to_string_lossy(), "update.lock");
625	        }
626	    }
627	}
