416	/// Convert a [`WorkflowFile`] into the partial `BivvyConfig` YAML value it
417	/// contributes to the merge chain.
418	///
419	/// Produces a mapping with `vars`, `steps`, and `workflows.<stem>` keys.
420	/// The workflow's description falls back to the file-level description
421	/// when not set inside the `workflow:` block.
422	fn workflow_file_to_partial(file: &WorkflowFile, stem: &str) -> Result<serde_yaml::Value> {
423	    let mut wrapper = serde_yaml::Mapping::new();
424	
425	    if !file.vars.is_empty() {
426	        let vars_value =
427	            serde_yaml::to_value(&file.vars).map_err(|e| BivvyError::ConfigParseError {
428	                path: PathBuf::from(format!(".bivvy/workflows/{stem}.yml")),
429	                message: format!("Failed to serialize workflow vars: {e}"),
430	            })?;
431	        wrapper.insert(serde_yaml::Value::String("vars".to_string()), vars_value);
432	    }
433	
434	    if !file.steps.is_empty() {
435	        let steps_value =
436	            serde_yaml::to_value(&file.steps).map_err(|e| BivvyError::ConfigParseError {
437	                path: PathBuf::from(format!(".bivvy/workflows/{stem}.yml")),
438	                message: format!("Failed to serialize workflow steps: {e}"),
439	            })?;
440	        wrapper.insert(serde_yaml::Value::String("steps".to_string()), steps_value);
441	    }
442	
443	    let mut workflow = file.workflow.clone();
444	    if workflow.description.is_none() {
445	        if let Some(ref desc) = file.description {
446	            workflow.description = Some(desc.clone());
447	        }
448	    }
449	
450	    let workflow_value =
451	        serde_yaml::to_value(&workflow).map_err(|e| BivvyError::ConfigParseError {
452	            path: PathBuf::from(format!(".bivvy/workflows/{stem}.yml")),
453	            message: format!("Failed to serialize workflow: {e}"),
454	        })?;
455	
456	    let mut workflows_map = serde_yaml::Mapping::new();
457	    workflows_map.insert(serde_yaml::Value::String(stem.to_string()), workflow_value);
458	    wrapper.insert(
459	        serde_yaml::Value::String("workflows".to_string()),
460	        serde_yaml::Value::Mapping(workflows_map),
461	    );
462	
463	    Ok(serde_yaml::Value::Mapping(wrapper))
464	}
