pub fn fetch_with_auth(&self, url: &str, auth: &AuthHeader) -> Result<String> {
    if !url.starts_with("https://") {
        return Err(BivvyError::UntrustedUrl {
            url: format!(
                "Refusing to send auth headers over insecure HTTP: {}. Use HTTPS instead",
                url
            ),
        });
    }

    let response = self
        .client
        .get(url)
        .header(&auth.header_name, &auth.header_value)
        .send()
        .map_err(|e| BivvyError::NetworkError {
            url: url.to_string(),
            message: format!("Failed to fetch {}: {}", url, e),
        })?;

    if !response.status().is_success() {
        return Err(BivvyError::NetworkError {
            url: url.to_string(),
            message: format!("HTTP {}", response.status()),
        });
    }

    response.text().map_err(|e| BivvyError::NetworkError {
        url: url.to_string(),
        message: format!("Failed to read response from {}: {}", url, e),
    })
}

