138	    fn install_method_provides_update_command() {
139	        let cargo = InstallMethod::Cargo;
140	        assert!(cargo.update_command().is_some());
141	
142	        let homebrew = InstallMethod::Homebrew;
143	        assert!(homebrew.update_command().is_some());
144	    }
