147	    fn check_and_prompt_update_non_interactive() {
148	        let mut ui = MockUI::new();
149	        // MockUI is non-interactive, so this should return false
150	        let result = check_and_prompt_update(&mut ui).unwrap();
151	        assert!(!result);
152	    }
