198	        let mut ui = MockUI::new();
199	        let info = UpdateInfo {
200	            current: "0.1.0".to_string(),
201	            latest: "0.2.0".to_string(),
202	            update_available: true,
203	            release_url: None,
204	            checked_at: Utc::now(),
205	        };
206	        let method = InstallMethod::Unknown;
207	
208	        let result = prompt_for_update(&mut ui, &info, &method).unwrap();
