fn fetch_remote(&self, url: &str) -> Result<String> {
    let response = self
        .client
        .get(url)
        .send()
        .map_err(|e| BivvyError::NetworkError {
            url: url.to_string(),
            message: format!("Failed to fetch {}: {}", url, e),
        })?;

    if !response.status().is_success() {
        return Err(BivvyError::NetworkError {
            url: url.to_string(),
            message: format!("HTTP {}", response.status()),
        });
    }

    response.text().map_err(|e| BivvyError::NetworkError {
        url: url.to_string(),
        message: format!("Failed to read response from {}: {}", url, e),
    })
}

