160	                workflow: "default".to_string(),
161	                completed_steps: vec!["step1".to_string()],
162	                pending_step: "step2".to_string(),
163	                timestamp: chrono::Utc::now(),
164	            };
165	
166	            state.save().unwrap();
167	            let loaded = ResumeState::load().unwrap().unwrap();
168	
169	            assert_eq!(loaded.workflow, "default");
170	            assert_eq!(loaded.completed_steps.len(), 1);
