178	            let state = ResumeState {
179	                project_root: PathBuf::from("/test"),
180	                workflow: "default".to_string(),
181	                completed_steps: vec![],
182	                pending_step: "step1".to_string(),
183	                timestamp: chrono::Utc::now(),
184	            };
185	
186	            state.save().unwrap();
187	            assert!(ResumeState::exists());
188	
189	            ResumeState::clear().unwrap();
190	            assert!(!ResumeState::exists());
191	            assert!(ResumeState::load().unwrap().is_none());
192	        });
193	    }
194	
195	    #[test]
196	    fn load_returns_none_when_no_state() {
197	        with_temp_state(|| {
198	            let loaded = ResumeState::load().unwrap();
199	            assert!(loaded.is_none());
200	        });
201	    }
202	
203	    #[test]
204	    fn exists_returns_false_when_no_state() {
205	        with_temp_state(|| {
206	            assert!(!ResumeState::exists());
207	        });
208	    }
