1	//! Cache storage implementation.
2	
3	use sha2::{Digest, Sha256};
4	use std::fs;
5	use std::path::{Path, PathBuf};
6	
7	use crate::error::{BivvyError, Result};
8	
9	use super::entry::CacheEntry;
10	
11	/// Storage for cached templates.
12	pub struct CacheStore {
13	    /// Root directory for cache.
14	    root: PathBuf,
15	}
16	
17	impl CacheStore {
18	    /// Create a new cache store.
19	    pub fn new(root: impl Into<PathBuf>) -> Self {
20	        Self { root: root.into() }
21	    }
22	
23	    /// Get the cache root directory.
24	    pub fn root(&self) -> &Path {
25	        &self.root
26	    }
27	
28	    /// Ensure the cache directory exists.
29	    fn ensure_dir(&self) -> Result<()> {
30	        fs::create_dir_all(&self.root).map_err(|e| BivvyError::CacheError {
31	            message: format!("Failed to create cache directory {:?}: {}", self.root, e),
32	        })
33	    }
34	
35	    /// Get the path for storing an entry's content.
36	    pub fn content_path(&self, source_id: &str, template_name: &str) -> PathBuf {
37	        let key = format!("{}:{}", source_id, template_name);
38	        let hash = Sha256::digest(key.as_bytes());
39	        let hash_str = hex::encode(&hash[..16]);
40	        self.root.join(hash_str)
41	    }
42	
43	    /// Get the metadata file path for an entry.
44	    fn metadata_path(&self, source_id: &str, template_name: &str) -> PathBuf {
45	        self.content_path(source_id, template_name)
46	            .with_extension("meta.json")
47	    }
48	
49	    /// Store content and return a cache entry.
50	    pub fn store(
51	        &self,
52	        source_id: &str,
53	        template_name: &str,
54	        content: &str,
55	        ttl_seconds: u64,
56	    ) -> Result<CacheEntry> {
57	        self.ensure_dir()?;
58	
59	        let content_path = self.content_path(source_id, template_name);
60	        fs::write(&content_path, content)?;
61	
62	        let entry = CacheEntry::new(source_id, template_name, &content_path, ttl_seconds)
63	            .with_size(content.len() as u64);
64	
65	        self.save_metadata(&entry)?;
66	
67	        Ok(entry)
68	    }
69	
70	    /// Load a cached entry's metadata.
71	    pub fn load(&self, source_id: &str, template_name: &str) -> Result<Option<CacheEntry>> {
72	        let meta_path = self.metadata_path(source_id, template_name);
73	
74	        if !meta_path.exists() {
75	            return Ok(None);
76	        }
77	
78	        let json = fs::read_to_string(&meta_path)?;
79	        let entry: CacheEntry = serde_json::from_str(&json)?;
80	
81	        Ok(Some(entry))
82	    }
83	
84	    /// Read the cached content.
85	    pub fn read_content(&self, entry: &CacheEntry) -> Result<String> {
86	        fs::read_to_string(&entry.content_path).map_err(|e| BivvyError::CacheError {
87	            message: format!(
88	                "Failed to read cached content from {:?}: {}",
89	                entry.content_path, e
90	            ),
91	        })
92	    }
93	
94	    /// Save entry metadata.
95	    fn save_metadata(&self, entry: &CacheEntry) -> Result<()> {
96	        let meta_path = self.metadata_path(&entry.source_id, &entry.template_name);
97	        let json = serde_json::to_string_pretty(entry)?;
98	        fs::write(&meta_path, json)?;
99	        Ok(())
100	    }
101	
102	    /// Update an entry's metadata (e.g., after revalidation).
103	    pub fn update(&self, entry: &CacheEntry) -> Result<()> {
104	        self.save_metadata(entry)
105	    }
106	
107	    /// Remove a cached entry.
108	    pub fn remove(&self, source_id: &str, template_name: &str) -> Result<bool> {
109	        let content_path = self.content_path(source_id, template_name);
110	        let meta_path = self.metadata_path(source_id, template_name);
111	
112	        let mut removed = false;
113	
114	        if content_path.exists() {
115	            fs::remove_file(&content_path)?;
116	            removed = true;
117	        }
118	
119	        if meta_path.exists() {
120	            fs::remove_file(&meta_path)?;
121	            removed = true;
122	        }
123	
124	        Ok(removed)
125	    }
126	
127	    /// List all cached entries.
128	    pub fn list(&self) -> Result<Vec<CacheEntry>> {
129	        self.ensure_dir()?;
130	
131	        let mut entries = Vec::new();
132	
133	        for entry in fs::read_dir(&self.root)? {
134	            let entry = entry?;
135	            let path = entry.path();
136	
137	            if path.extension().is_some_and(|e| e == "json") {
138	                if let Ok(json) = fs::read_to_string(&path) {
139	                    if let Ok(cache_entry) = serde_json::from_str::<CacheEntry>(&json) {
140	                        entries.push(cache_entry);
141	                    }
142	                }
143	            }
144	        }
145	
146	        entries.sort_by_key(|e| std::cmp::Reverse(e.metadata.cached_at));
147	        Ok(entries)
148	    }
149	
150	    /// Clear all cached entries.
151	    pub fn clear(&self) -> Result<usize> {
152	        let entries = self.list()?;
153	        let count = entries.len();
154	
155	        for entry in entries {
156	            let _ = self.remove(&entry.source_id, &entry.template_name);
157	        }
158	
159	        Ok(count)
160	    }
161	
162	    /// Get total cache size in bytes.
163	    pub fn total_size(&self) -> Result<u64> {
164	        let entries = self.list()?;
165	        Ok(entries.iter().map(|e| e.metadata.size_bytes).sum())
166	    }
167	}
