1	//! Cache revalidation for ETag and git strategies.
2	
3	use super::{CacheEntry, CacheStore, ValidationResult};
4	use crate::error::{BivvyError, Result};
5	use crate::registry::fetch::{GitFetcher, HttpFetcher};
6	
7	/// Performs cache revalidation using ETag or git checking.
8	pub struct CacheRevalidator<'a> {
9	    store: &'a CacheStore,
10	    http: HttpFetcher,
11	    git: GitFetcher,
12	}
13	
14	/// Result of revalidation.
15	#[derive(Debug)]
16	pub enum RevalidationResult {
17	    /// Content unchanged, cache extended.
18	    Unchanged,
19	    /// Content changed, new content available.
20	    Updated(String),
21	    /// Revalidation failed (fallback to cache or error).
22	    Failed(String),
23	}
24	
25	impl<'a> CacheRevalidator<'a> {
26	    /// Create a new revalidator.
27	    pub fn new(store: &'a CacheStore, git_clone_dir: impl Into<std::path::PathBuf>) -> Self {
28	        Self {
29	            store,
30	            http: HttpFetcher::new(),
31	            git: GitFetcher::new(git_clone_dir),
32	        }
33	    }
34	
35	    /// Revalidate an entry using its ETag.
36	    pub fn revalidate_etag(
37	        &self,
38	        url: &str,
39	        entry: &mut CacheEntry,
40	        new_ttl_seconds: u64,
41	    ) -> Result<RevalidationResult> {
42	        let etag = entry.metadata.etag.as_deref();
43	
44	        match self
45	            .http
46	            .fetch_if_changed(url, etag)
47	            .map_err(|e| BivvyError::CacheError {
48	                message: format!("ETag revalidation failed for {}: {}", url, e),
49	            })? {
50	            None => {
51	                // 304 Not Modified - extend TTL
52	                entry.metadata.expires_at =
53	                    chrono::Utc::now() + chrono::Duration::seconds(new_ttl_seconds as i64);
54	                self.store.update(entry)?;
55	                Ok(RevalidationResult::Unchanged)
56	            }
57	            Some(response) => {
58	                // Content changed - update cache
59	                let content_path = self
60	                    .store
61	                    .content_path(&entry.source_id, &entry.template_name);
62	                std::fs::write(&content_path, &response.content)?;
63	
64	                entry.metadata.etag = response.etag;
65	                entry.metadata.size_bytes = response.content.len() as u64;
66	                entry.metadata.cached_at = chrono::Utc::now();
67	                entry.metadata.expires_at =
68	                    chrono::Utc::now() + chrono::Duration::seconds(new_ttl_seconds as i64);
69	                self.store.update(entry)?;
70	
71	                Ok(RevalidationResult::Updated(response.content))
72	            }
73	        }
74	    }
75	
76	    /// Revalidate an entry using git commit comparison.
77	    pub fn revalidate_git(
78	        &self,
79	        url: &str,
80	        git_ref: Option<&str>,
81	        entry: &mut CacheEntry,
82	        new_ttl_seconds: u64,
83	    ) -> Result<RevalidationResult> {
84	        let current_sha = match &entry.metadata.commit_sha {
85	            Some(sha) => sha.clone(),
86	            None => {
87	                // No SHA to compare, must re-fetch
88	                return self.fetch_git(url, git_ref, entry, new_ttl_seconds);
89	            }
90	        };
91	
92	        let has_updates = self
93	            .git
94	            .has_updates(url, git_ref, &current_sha)
95	            .map_err(|e| BivvyError::CacheError {
96	                message: format!("Git revalidation check failed for {}: {}", url, e),
97	            })?;
98	
99	        if has_updates {
100	            self.fetch_git(url, git_ref, entry, new_ttl_seconds)
101	        } else {
102	            // No updates - extend TTL
103	            entry.metadata.expires_at =
104	                chrono::Utc::now() + chrono::Duration::seconds(new_ttl_seconds as i64);
105	            self.store.update(entry)?;
106	            Ok(RevalidationResult::Unchanged)
107	        }
108	    }
109	
110	    /// Fetch from git and update the cache entry.
111	    fn fetch_git(
112	        &self,
113	        url: &str,
114	        git_ref: Option<&str>,
115	        entry: &mut CacheEntry,
116	        new_ttl_seconds: u64,
117	    ) -> Result<RevalidationResult> {
118	        let result =
119	            self.git
120	                .fetch(url, git_ref)
121	                .map_err(|e| BivvyError::CacheError {
122	                    message: format!("Git fetch failed for {}: {}", url, e),
123	                })?;
124	
125	        // Copy content from cloned repo to cache
126	        let content_path = self
127	            .store
128	            .content_path(&entry.source_id, &entry.template_name);
129	
130	        // For git sources, we store a marker that the content is at the git path
131	        let content = format!("git-path:{}", result.local_path.display());
132	        std::fs::write(&content_path, &content)?;
133	
134	        entry.metadata.commit_sha = Some(result.commit_sha);
135	        entry.metadata.cached_at = chrono::Utc::now();
136	        entry.metadata.expires_at =
137	            chrono::Utc::now() + chrono::Duration::seconds(new_ttl_seconds as i64);
138	        self.store.update(entry)?;
139	
140	        Ok(RevalidationResult::Updated(content))
141	    }
142	}
143	
144	/// Check if a validation result needs revalidation.
145	pub fn needs_revalidation(result: &ValidationResult) -> bool {
146	    matches!(result, ValidationResult::NeedsRevalidation)
147	}
