1	//! Version checking against latest release.
2	
3	use crate::error::{BivvyError, Result};
4	use chrono::{DateTime, Utc};
5	use serde::{Deserialize, Serialize};
6	use std::fs;
7	use std::path::PathBuf;
8	
9	/// Current version of bivvy.
10	pub const VERSION: &str = env!("CARGO_PKG_VERSION");
11	
12	/// GitHub API URL for releases.
13	const GITHUB_API_URL: &str = "https://api.github.com/repos/bivvy-dev/bivvy/releases/latest";
14	
15	/// How often to check for updates (1 day).
16	const CHECK_INTERVAL_SECS: i64 = 86400;
17	
18	/// Information about an available update.
19	#[derive(Debug, Clone, Serialize, Deserialize)]
20	pub struct UpdateInfo {
21	    /// Current version.
22	    pub current: String,
23	    /// Latest available version.
24	    pub latest: String,
25	    /// Whether an update is available.
26	    pub update_available: bool,
27	    /// Release URL.
28	    pub release_url: Option<String>,
29	    /// When this check was performed.
30	    pub checked_at: DateTime<Utc>,
31	}
32	
33	/// Cached update check result.
34	#[derive(Debug, Clone, Serialize, Deserialize)]
35	struct UpdateCache {
36	    /// Last update info.
37	    info: UpdateInfo,
38	    /// When the cache was written.
39	    cached_at: DateTime<Utc>,
40	}
41	
42	/// Check for available updates.
43	///
44	/// Returns cached result if within check interval.
45	pub fn check_for_updates() -> Option<UpdateInfo> {
46	    // Check cache first
47	    if let Some(cached) = load_cache() {
48	        let age = Utc::now()
49	            .signed_duration_since(cached.cached_at)
50	            .num_seconds();
51	        if age < CHECK_INTERVAL_SECS {
52	            return Some(cached.info);
53	        }
54	    }
55	
56	    // Fetch latest version
57	    match fetch_latest_version() {
58	        Ok(info) => {
59	            // Cache the result
60	            let _ = save_cache(&info);
61	            Some(info)
62	        }
63	        Err(_) => {
64	            // Return cached result even if expired
65	            load_cache().map(|c| c.info)
66	        }
67	    }
68	}
69	
70	/// Check for updates without using cache.
71	pub fn check_for_updates_fresh() -> Result<UpdateInfo> {
72	    fetch_latest_version()
73	}
74	
75	/// Fetch the latest version from GitHub.
76	fn fetch_latest_version() -> Result<UpdateInfo> {
77	    let client = reqwest::blocking::Client::builder()
78	        .user_agent("bivvy")
79	        .timeout(std::time::Duration::from_secs(10))
80	        .build()
81	        .map_err(|e| BivvyError::NetworkError { url: GITHUB_API_URL.to_string(), message: e.to_string() })?;
82	
83	    let response: serde_json::Value = client
84	        .get(GITHUB_API_URL)
85	        .send()
86	        .map_err(|e| BivvyError::NetworkError { url: GITHUB_API_URL.to_string(), message: e.to_string() })?
87	        .json()
88	        .map_err(|e| BivvyError::UpdateError { message: format!("Failed to parse GitHub API response: {}", e) })?;
89	
90	    let tag = response["tag_name"]
91	        .as_str()
92	        .ok_or_else(|| BivvyError::UpdateError { message: "No tag_name in response".into() })?
93	        .trim_start_matches('v');
94	
95	    let release_url = response["html_url"].as_str().map(String::from);
96	
97	    let update_available = is_newer_version(tag, VERSION);
98	
99	    Ok(UpdateInfo {
100	        current: VERSION.to_string(),
101	        latest: tag.to_string(),
102	        update_available,
103	        release_url,
104	        checked_at: Utc::now(),
105	    })
106	}
107	
108	/// Compare versions to check if `latest` is newer than `current`.
109	fn is_newer_version(latest: &str, current: &str) -> bool {
110	    let parse_version = |v: &str| -> Vec<u32> {
111	        v.split('.')
112	            .take(3)
113	            .filter_map(|s| s.parse().ok())
114	            .collect()
115	    };
116	
117	    let latest_parts = parse_version(latest);
118	    let current_parts = parse_version(current);
119	
120	    // Compare component by component
121	    for (l, c) in latest_parts.iter().zip(current_parts.iter()) {
122	        if l > c {
123	            return true;
124	        }
125	        if l < c {
126	            return false;
127	        }
128	    }
129	
130	    // If all components equal, check if latest has more components
131	    latest_parts.len() > current_parts.len()
132	}
133	
134	/// Get the cache file path.
135	fn cache_path() -> Option<PathBuf> {
136	    crate::sys::cache_dir().map(|d| d.join("bivvy").join("update_check.json"))
137	}
138	
139	/// Load cached update info.
140	fn load_cache() -> Option<UpdateCache> {
141	    let path = cache_path()?;
142	    let content = fs::read_to_string(path).ok()?;
143	    serde_json::from_str(&content).ok()
144	}
145	
146	/// Save update info to cache.
147	fn save_cache(info: &UpdateInfo) -> Result<()> {
148	    let path = cache_path().ok_or_else(|| BivvyError::UpdateError { message: "No cache directory".into() })?;
149	
150	    if let Some(parent) = path.parent() {
151	        fs::create_dir_all(parent)?;
152	    }
153	
154	    let cache = UpdateCache {
155	        info: info.clone(),
156	        cached_at: Utc::now(),
157	    };
158	
159	    let content = serde_json::to_string_pretty(&cache)?;
160	    fs::write(path, content)?;
161	
162	    Ok(())
163	}
164	
165	/// Clear the update check cache.
166	pub fn clear_cache() -> Result<()> {
167	    if let Some(path) = cache_path() {
168	        if path.exists() {
169	            fs::remove_file(path)?;
170	        }
171	    }
172	    Ok(())
173	}
174	
175	#[cfg(test)]
176	mod tests {
177	    use super::*;
178	
179	    #[test]
180	    fn version_constant_exists() {
181	        assert!(!VERSION.is_empty());
182	    }
183	
184	    #[test]
185	    fn is_newer_version_basic() {
186	        assert!(is_newer_version("0.2.0", "0.1.0"));
187	        assert!(is_newer_version("1.0.0", "0.9.0"));
188	        assert!(is_newer_version("0.1.1", "0.1.0"));
189	    }
190	
191	    #[test]
192	    fn is_newer_version_same() {
193	        assert!(!is_newer_version("0.1.0", "0.1.0"));
194	        assert!(!is_newer_version("1.0.0", "1.0.0"));
195	    }
196	
197	    #[test]
198	    fn is_newer_version_older() {
199	        assert!(!is_newer_version("0.1.0", "0.2.0"));
200	        assert!(!is_newer_version("0.9.0", "1.0.0"));
201	    }
202	
203	    #[test]
204	    fn update_info_creation() {
205	        let info = UpdateInfo {
206	            current: "0.1.0".to_string(),
207	            latest: "0.2.0".to_string(),
208	            update_available: true,
209	            release_url: Some("https://github.com/bivvy-dev/bivvy/releases".to_string()),
210	            checked_at: Utc::now(),
211	        };
212	
213	        assert!(info.update_available);
214	        assert_eq!(info.current, "0.1.0");
215	        assert_eq!(info.latest, "0.2.0");
216	    }
217	
218	    #[test]
219	    fn cache_path_is_valid() {
220	        let path = cache_path();
221	        // Should return a path on most systems
222	        if let Some(p) = path {
223	            assert!(p.ends_with("update_check.json"));
224	        }
225	    }
226	
227	    #[test]
228	    fn is_newer_version_handles_prerelease() {
229	        // Function only considers first 3 components
230	        // 0.1.0.1 and 0.1.0 are considered equal
231	        assert!(!is_newer_version("0.1.0.1", "0.1.0"));
232	    }
233	
234	    #[test]
235	    fn is_newer_version_major_bump() {
236	        assert!(is_newer_version("2.0.0", "1.9.9"));
237	        assert!(is_newer_version("10.0.0", "9.99.99"));
238	    }
239	
240	    #[test]
241	    fn is_newer_version_minor_bump() {
242	        assert!(is_newer_version("1.2.0", "1.1.99"));
243	        assert!(!is_newer_version("1.1.0", "1.2.0"));
244	    }
245	
246	    #[test]
247	    fn is_newer_version_patch_bump() {
248	        assert!(is_newer_version("1.0.5", "1.0.4"));
249	        assert!(!is_newer_version("1.0.4", "1.0.5"));
250	    }
251	
252	    #[test]
253	    fn is_newer_version_with_single_component() {
254	        assert!(is_newer_version("2", "1"));
255	        assert!(!is_newer_version("1", "2"));
256	    }
257	
258	    #[test]
259	    fn is_newer_version_with_two_components() {
260	        assert!(is_newer_version("1.1", "1.0"));
261	        assert!(!is_newer_version("1.0", "1.1"));
262	    }
263	
264	    #[test]
265	    fn clear_cache_works() {
266	        // Clear cache should not panic even if file doesn't exist
267	        let result = clear_cache();
268	        assert!(result.is_ok());
269	    }
270	
271	    #[test]
272	    fn update_info_serialization() {
273	        let info = UpdateInfo {
274	            current: "0.1.0".to_string(),
275	            latest: "0.2.0".to_string(),
276	            update_available: true,
277	            release_url: None,
278	            checked_at: Utc::now(),
279	        };
280	
281	        let json = serde_json::to_string(&info).unwrap();
282	        let parsed: UpdateInfo = serde_json::from_str(&json).unwrap();
283	
284	        assert_eq!(parsed.current, info.current);
285	        assert_eq!(parsed.latest, info.latest);
286	        assert_eq!(parsed.update_available, info.update_available);
287	    }
288	
289	    #[test]
290	    fn update_info_with_no_release_url() {
291	        let info = UpdateInfo {
292	            current: "0.1.0".to_string(),
293	            latest: "0.2.0".to_string(),
294	            update_available: false,
295	            release_url: None,
296	            checked_at: Utc::now(),
297	        };
298	
299	        assert!(!info.update_available);
300	        assert!(info.release_url.is_none());
301	    }
302	
303	    #[test]
304	    fn is_newer_version_empty_string() {
305	        // Edge case: empty strings
306	        // When latest is empty, it has no components, so can't be newer
307	        assert!(!is_newer_version("", "0.1.0"));
308	        // When current is empty, latest has more components, so is "newer"
309	        assert!(is_newer_version("0.1.0", ""));
310	    }
311	
312	    #[test]
313	    fn is_newer_version_invalid_format() {
314	        // Edge case: non-numeric components are filtered out
315	        // "abc" parses to empty vec, so can't be newer than 0.1.0
316	        assert!(!is_newer_version("abc", "0.1.0"));
317	        // Current "abc" parses to empty, so 0.1.0 is newer (has more components)
318	        assert!(is_newer_version("0.1.0", "abc"));
319	    }
320	}
