348	/// Download the appropriate binary from GitHub releases and stage it.
349	fn stage_binary_update(info: &UpdateInfo) -> Result<()> {
350	    let asset_url = find_platform_asset_url(info)?;
351	
352	    let dir = staging_dir().ok_or_else(|| BivvyError::UpdateError { message: "No data directory for staging".into() })?;
353	    fs::create_dir_all(&dir)?;
354	
355	    let binary_path = if cfg!(windows) {
356	        dir.join("bivvy.exe")
357	    } else {
358	        dir.join("bivvy")
359	    };
360	
361	    download_asset(&asset_url, &binary_path)?;
362	
363	    // Write metadata so apply_staged_update knows the version
364	    let metadata = StagedUpdate {
365	        version: info.latest.clone(),
366	        staged_at: Utc::now(),
367	    };
368	    let meta_path = dir.join("metadata.json");
369	    fs::write(meta_path, serde_json::to_string_pretty(&metadata)?)?;
370	
371	    Ok(())
372	}
373	
374	/// Query the GitHub releases API to find the download URL for this platform.
375	fn find_platform_asset_url(info: &UpdateInfo) -> Result<String> {
376	    let target = platform_target();
377	
378	    let api_url = format!(
379	        "https://api.github.com/repos/bivvy-dev/bivvy/releases/tags/v{}",
380	        info.latest
381	    );
382	
383	    let client = reqwest::blocking::Client::builder()
384	        .user_agent("bivvy")
385	        .timeout(std::time::Duration::from_secs(30))
386	        .build()
387	        .map_err(|e| BivvyError::NetworkError { url: api_url.clone(), message: e.to_string() })?;
388	
389	    let response: serde_json::Value = client
390	        .get(&api_url)
391	        .send()
392	        .map_err(|e| BivvyError::NetworkError { url: api_url.clone(), message: e.to_string() })?
393	        .json()
394	        .map_err(|e| BivvyError::UpdateError { message: format!("Failed to parse GitHub releases API response: {}", e) })?;
395	
396	    let assets = response["assets"]
397	        .as_array()
398	        .ok_or_else(|| BivvyError::UpdateError { message: "No assets array in release".into() })?;
399	
400	    for asset in assets {
401	        let name = asset["name"].as_str().unwrap_or("");
402	        if name.contains(&target) {
403	            if let Some(url) = asset["browser_download_url"].as_str() {
404	                return Ok(url.to_string());
405	            }
406	        }
407	    }
408	
409	    Err(BivvyError::UpdateError {
410	        message: format!("No release asset found for platform '{}' in v{}", target, info.latest),
411	    })
412	}
413	
414	/// Return the Rust target triple fragment for this platform.
415	///
416	/// Used to match against GitHub release asset filenames (e.g.
417	/// `bivvy-x86_64-apple-darwin`, `bivvy-aarch64-unknown-linux-gnu`).
418	pub fn platform_target() -> String {
419	    let os = match std::env::consts::OS {
420	        "macos" => "apple-darwin",
421	        "linux" => "unknown-linux-gnu",
422	        "windows" => "pc-windows-msvc",
423	        other => other,
424	    };
425	
426	    let arch = std::env::consts::ARCH;
427	
428	    format!("{}-{}", arch, os)
429	}
430	
431	/// Download a file from a URL to a local path.
432	fn download_asset(url: &str, dest: &PathBuf) -> Result<()> {
433	    let client = reqwest::blocking::Client::builder()
434	        .user_agent("bivvy")
435	        .timeout(std::time::Duration::from_secs(120))
436	        .build()
437	        .map_err(|e| BivvyError::NetworkError { url: url.to_string(), message: e.to_string() })?;
438	
439	    let bytes = client
440	        .get(url)
441	        .send()
442	        .map_err(|e| BivvyError::NetworkError { url: url.to_string(), message: e.to_string() })?
443	        .bytes()
444	        .map_err(|e| BivvyError::NetworkError { url: url.to_string(), message: format!("Failed to read download body: {}", e) })?;
445	
446	    fs::write(dest, &bytes)?;
447	
448	    // Make executable on Unix
449	    #[cfg(unix)]
450	    {
451	        use std::os::unix::fs::PermissionsExt;
452	        let mut perms = fs::metadata(dest)?.permissions();
453	        perms.set_mode(0o755);
454	        fs::set_permissions(dest, perms)?;
455	    }
456	
457	    Ok(())
458	}
