1	//! Error types for Bivvy operations.
2	//!
3	//! This module defines [`BivvyError`], the primary error type used throughout
4	//! the application, and a [`Result`] type alias for convenience.
5	//!
6	//! # Error Handling Strategy
7	//!
8	//! - Use `BivvyError` for domain-specific errors that need distinct handling
9	//! - All errors should provide actionable messages for users
10	
11	use std::path::PathBuf;
12	use thiserror::Error;
13	
14	/// Core error type for Bivvy operations.
15	#[derive(Debug, Error)]
16	pub enum BivvyError {
17	    /// Configuration file not found at expected location.
18	    #[error("Configuration not found: {path}")]
19	    ConfigNotFound { path: PathBuf },
20	
21	    /// Failed to parse configuration file.
22	    #[error("Failed to parse config at {path}: {message}")]
23	    ConfigParseError { path: PathBuf, message: String },
24	
25	    /// Invalid configuration structure or values.
26	    #[error("Invalid configuration: {message}")]
27	    ConfigValidationError { message: String },
28	
29	    /// Referenced template does not exist.
30	    #[error("Unknown template: {name}")]
31	    UnknownTemplate { name: String },
32	
33	    /// Step dependency cycle detected.
34	    #[error("Circular dependency detected: {cycle}")]
35	    CircularDependency { cycle: String },
36	
37	    /// Step execution failed.
38	    #[error("Step '{step}' failed: {message}")]
39	    StepExecutionError { step: String, message: String },
40	
41	    /// Shell command failed.
42	    #[error("Command failed with exit code {code:?}: {command}")]
43	    CommandFailed { command: String, code: Option<i32> },
44	
45	    /// A required tool or service is missing and cannot be auto-installed.
46	    #[error("Missing requirement '{requirement}': {message}")]
47	    RequirementMissing {
48	        requirement: String,
49	        message: String,
50	    },
51	
52	    /// A requirement check failed unexpectedly (e.g., network error during install).
53	    #[error("Requirement check failed for '{requirement}': {message}")]
54	    RequirementCheckFailed {
55	        requirement: String,
56	        message: String,
57	    },
58	
59	    /// An untrusted remote URL was encountered in non-interactive mode.
60	    #[error("Untrusted remote config URL: {url}. Use --trust to auto-approve or run interactively to confirm.")]
61	    UntrustedUrl { url: String },
62	
63	    /// Shell operation failed (e.g., spawning a debug shell).
64	    #[error("Shell error: {message}")]
65	    ShellError { message: String },
66	
67	    /// IO error wrapper.
68	    #[error("IO error: {0}")]
69	    Io(#[from] std::io::Error),
70	
71	    /// Cache subsystem error.
72	    #[error("Cache error: {message}")]
73	    CacheError { message: String },
74	
75	    /// Network request failed.
76	    #[error("Network error for {url}: {message}")]
77	    NetworkError { url: String, message: String },
78	
79	    /// Config extension resolution failed.
80	    #[error("Extends error: {message}")]
81	    ExtendsError { message: String },
82	
83	    /// Session subsystem error.
84	    #[error("Session error: {message}")]
85	    SessionError { message: String },
86	
87	    /// Feedback subsystem error.
88	    #[error("Feedback error: {message}")]
89	    FeedbackError { message: String },
90	
91	    /// Update subsystem error.
92	    #[error("Update error: {message}")]
93	    UpdateError { message: String },
94	
95	    /// Git operation failed.
96	    #[error("Git error: {message}")]
97	    GitError { message: String },
98	
99	    /// Serialization or deserialization failed.
100	    #[error("Serialization error: {message}")]
101	    SerializationError { message: String },
102	}
103	
104	impl From<serde_json::Error> for BivvyError {
105	    fn from(err: serde_json::Error) -> Self {
106	        BivvyError::SerializationError {
107	            message: err.to_string(),
108	        }
109	    }
110	}
