113	    fn from(err: serde_yaml::Error) -> Self {
114	        BivvyError::SerializationError {
115	            message: err.to_string(),
116	        }
117	    }
118	}
119	
120	impl From<std::num::ParseIntError> for BivvyError {
121	    fn from(err: std::num::ParseIntError) -> Self {
122	        BivvyError::ConfigValidationError {
123	            message: err.to_string(),
124	        }
125	    }
126	}
