1	//! HTTP template fetching.
2	//!
3	//! Provides an HTTP client for fetching templates from URLs with
4	//! support for ETag-based conditional requests.
5	
6	use crate::error::{BivvyError, Result};
7	use reqwest::blocking::Client;
8	use std::time::Duration;
9	
10	/// Default maximum response body size (10 MB).
11	const DEFAULT_MAX_RESPONSE_SIZE: u64 = 10 * 1024 * 1024;
12	
13	/// Fetches templates over HTTP/HTTPS.
14	pub struct HttpFetcher {
15	    client: Client,
16	    timeout: Duration,
17	    max_response_size: u64,
18	}
19	
20	/// Response from fetching a template.
21	#[derive(Debug)]
22	pub struct FetchResponse {
23	    /// The template content.
24	    pub content: String,
25	    /// ETag header if present.
26	    pub etag: Option<String>,
27	    /// Last-Modified header if present.
28	    pub last_modified: Option<String>,
29	}
30	
31	impl HttpFetcher {
32	    /// Create a new HTTP fetcher with default 30-second timeout.
33	    pub fn new() -> Self {
34	        Self::with_timeout(Duration::from_secs(30))
35	    }
36	
37	    /// Create a new HTTP fetcher with custom timeout.
38	    pub fn with_timeout(timeout: Duration) -> Self {
39	        Self {
40	            client: Client::builder()
41	                .user_agent("bivvy")
42	                .timeout(timeout)
43	                .build()
44	                .expect("Failed to build HTTP client"),
45	            timeout,
46	            max_response_size: DEFAULT_MAX_RESPONSE_SIZE,
47	        }
48	    }
49	
50	    /// Create a new HTTP fetcher with custom timeout and max response size.
51	    #[cfg(test)]
52	    pub fn with_max_size(timeout: Duration, max_response_size: u64) -> Self {
53	        Self {
54	            client: Client::builder()
55	                .user_agent("bivvy")
56	                .timeout(timeout)
57	                .build()
58	                .expect("Failed to build HTTP client"),
59	            timeout,
60	            max_response_size,
61	        }
62	    }
63	
64	    /// Get the configured timeout.
65	    pub fn timeout(&self) -> Duration {
66	        self.timeout
67	    }
68	
69	    /// Fetch a template from a URL.
70	    pub fn fetch(&self, url: &str) -> Result<FetchResponse> {
71	        let response = self.client.get(url).send()?;
72	
73	        if !response.status().is_success() {
74	            return Err(BivvyError::NetworkError {
75	                url: url.to_string(),
76	                message: format!("HTTP {}", response.status()),
77	            });
78	        }
79	
80	        // Check Content-Length if available
81	        if let Some(len) = response.content_length() {
82	            if len > self.max_response_size {
83	                return Err(BivvyError::NetworkError {
84	                    url: url.to_string(),
85	                    message: format!(
86	                        "Response too large ({} bytes, max {} bytes)",
87	                        len, self.max_response_size
88	                    ),
89	                });
90	            }
91	        }
92	
93	        let etag = response
94	            .headers()
95	            .get("etag")
96	            .and_then(|v| v.to_str().ok())
97	            .map(String::from);
98	
99	        let last_modified = response
100	            .headers()
101	            .get("last-modified")
102	            .and_then(|v| v.to_str().ok())
103	            .map(String::from);
104	
105	        let content = response.text()?;
106	
107	        // Also check actual content size (in case Content-Length was missing/wrong)
108	        if content.len() as u64 > self.max_response_size {
109	            return Err(BivvyError::NetworkError {
110	                url: url.to_string(),
111	                message: format!(
112	                    "Response too large ({} bytes, max {} bytes)",
113	                    content.len(), self.max_response_size
114	                ),
115	            });
116	        }
117	
118	        Ok(FetchResponse {
119	            content,
120	            etag,
121	            last_modified,
122	        })
123	    }
124	
125	    /// Fetch with conditional request (If-None-Match).
126	    ///
127	    /// Returns `None` if content unchanged (304 Not Modified).
128	    pub fn fetch_if_changed(&self, url: &str, etag: Option<&str>) -> Result<Option<FetchResponse>> {
129	        let mut request = self.client.get(url);
130	
131	        if let Some(etag) = etag {
132	            request = request.header("If-None-Match", etag);
133	        }
134	
135	        let response = request.send()?;
136	
137	        if response.status() == reqwest::StatusCode::NOT_MODIFIED {
138	            return Ok(None);
139	        }
140	
141	        if !response.status().is_success() {
142	            return Err(BivvyError::NetworkError {
143	                url: url.to_string(),
144	                message: format!("HTTP {}", response.status()),
145	            });
146	        }
147	
148	        // Check Content-Length if available
149	        if let Some(len) = response.content_length() {
150	            if len > self.max_response_size {
151	                return Err(BivvyError::NetworkError {
152	                    url: url.to_string(),
153	                    message: format!(
154	                        "Response too large ({} bytes, max {} bytes)",
155	                        len, self.max_response_size
156	                    ),
157	                });
158	            }
159	        }
160	
161	        let new_etag = response
162	            .headers()
163	            .get("etag")
164	            .and_then(|v| v.to_str().ok())
165	            .map(String::from);
166	
167	        let last_modified = response
168	            .headers()
169	            .get("last-modified")
170	            .and_then(|v| v.to_str().ok())
171	            .map(String::from);
172	
173	        let content = response.text()?;
174	
175	        // Also check actual content size
176	        if content.len() as u64 > self.max_response_size {
177	            return Err(BivvyError::NetworkError {
178	                url: url.to_string(),
179	                message: format!(
180	                    "Response too large ({} bytes, max {} bytes)",
181	                    content.len(), self.max_response_size
182	                ),
183	            });
184	        }
185	
186	        Ok(Some(FetchResponse {
187	            content,
188	            etag: new_etag,
189	            last_modified,
190	        }))
191	    }
192	}
